// Generated by esquadro: do not edit. A date, or a date and a time, in the
// form: a calendar in a popover (shadcn/ui's), in the frontend's language,
// with Today and Clear; the time beside it, in hours and minutes.
import { ptBR } from "date-fns/locale"
import { Calendar as CalendarIcon, X } from "../icons.gen.ts"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import { locale } from "../config.ts"
import { t } from "./i18n.ts"

const TRIGGER =
  "h-11 w-full justify-start rounded-lg border-transparent bg-input px-3 font-medium shadow-none hover:bg-input/80 dark:bg-input dark:hover:bg-input/80 aria-invalid:border-destructive"

const pad = (n: number) => String(n).padStart(2, "0")

/** A date as the API writes it: 2026-11-18. */
export function dateParam(d: Date): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

/** A date the API wrote, as a day of the calendar (no time zone shift). */
export function dateOf(value: string): Date | undefined {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(value)
  return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : undefined
}

/** A calendar of years around today: a birth date as well as a due one. */
function DayPicker({ selected, onSelect }: { selected?: Date; onSelect: (d: Date | undefined) => void }) {
  const year = new Date().getFullYear()
  return (
    <Calendar
      mode="single"
      captionLayout="dropdown"
      startMonth={new Date(year - 100, 0)}
      endMonth={new Date(year + 20, 11)}
      defaultMonth={selected}
      selected={selected}
      onSelect={onSelect}
      locale={locale === "pt-BR" ? ptBR : undefined}
    />
  )
}

/** A date: the calendar in a popover, Today and Clear. */
export function DateInput({ id, value, onChange, invalid }: { id: string; value: string; onChange: (v: string | null) => void; invalid?: boolean }) {
  const [open, setOpen] = useState(false)
  const day = dateOf(value)
  const pick = (d: Date | undefined) => {
    onChange(d ? dateParam(d) : null)
    setOpen(false)
  }
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button id={id} type="button" variant="outline" aria-invalid={invalid} className={cn(TRIGGER, !day && "text-muted-foreground")}>
          <CalendarIcon />
          {day ? day.toLocaleDateString(locale, { day: "numeric", month: "long", year: "numeric" }) : t("pickDate")}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-2" align="start">
        <DayPicker selected={day} onSelect={pick} />
        <div className="flex justify-between gap-2 px-2 pb-1">
          <Button type="button" variant="ghost" size="sm" onClick={() => pick(new Date())}>
            {t("today")}
          </Button>
          {day && (
            <Button type="button" variant="ghost" size="sm" className="text-muted-foreground" onClick={() => pick(undefined)}>
              <X /> {t("clear")}
            </Button>
          )}
        </div>
      </PopoverContent>
    </Popover>
  )
}

/** A date and a time: the calendar and hours and minutes, in a popover. */
export function DateTimeInput({ id, value, onChange, invalid }: { id: string; value: string; onChange: (v: string | null) => void; invalid?: boolean }) {
  const [open, setOpen] = useState(false)
  const at = value ? new Date(value) : undefined
  const valid = at && !Number.isNaN(at.getTime()) ? at : undefined
  const time = valid ? `${pad(valid.getHours())}:${pad(valid.getMinutes())}` : ""
  // A day keeps the time it had (or the time it is now); a time, the day.
  const set = (day: Date | undefined, hhmm: string) => {
    if (!day) return onChange(null)
    const [h, m] = (hhmm || `${pad(new Date().getHours())}:${pad(new Date().getMinutes())}`).split(":").map(Number)
    onChange(new Date(day.getFullYear(), day.getMonth(), day.getDate(), h, m).toISOString())
  }
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button id={id} type="button" variant="outline" aria-invalid={invalid} className={cn(TRIGGER, !valid && "text-muted-foreground")}>
          <CalendarIcon />
          {valid ? valid.toLocaleString(locale, { day: "numeric", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" }) : t("pickDateTime")}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-2" align="start">
        <DayPicker selected={valid} onSelect={(d) => set(d, time)} />
        <div className="flex items-center gap-2 px-2 pb-1">
          <Input
            type="time"
            aria-label={t("time")}
            className="h-9 w-28"
            value={time}
            onChange={(e) => set(valid ?? new Date(), e.target.value)}
          />
          <Button type="button" variant="ghost" size="sm" onClick={() => set(new Date(), "")}>
            {t("now")}
          </Button>
          {valid && (
            <Button type="button" variant="ghost" size="sm" className="ml-auto text-muted-foreground" onClick={() => set(undefined, "")}>
              <X /> {t("clear")}
            </Button>
          )}
          <Button type="button" size="sm" className={cn(!valid && "ml-auto")} onClick={() => setOpen(false)}>
            {t("ok")}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}
